const input = $input.first().json;

// Create a lookup map for closing prices by stock symbol
const closeMap = new Map(
  (input.data || []).map(item => [
    item.symbol,
    Number(item.close)
  ])
);

// Calculate price changes for each stock in the portfolio
const results = (input.stock_list || []).map(stock => {
  const costPrice = Number(stock.costPrice);
  const close = closeMap.get(stock.symbol);

  const quantity = Number(stock.quantity || 0);
  const sellableQuantity = Number(stock.sellableQuantity || 0);

  // Handle stocks with missing closing prices
  if (close === undefined || !Number.isFinite(close)) {
    return {
      symbol: stock.symbol,
      quantity,
      sellableQuantity,
      close: null,
      costPrice,
      changePercent: null,
      status: "missing_close"
    };
  }

  // Calculate percentage change relative to the cost price
  const changePercent = costPrice > 0
    ? ((close - costPrice) / costPrice) * 100
    : null;

  return {
    symbol: stock.symbol,
    quantity,
    sellableQuantity,
    close,
    costPrice,
    changePercent: changePercent === null
      ? null
      : Number(changePercent.toFixed(2)),
    status: costPrice <= 0
      ? "invalid_cost"
      : changePercent > 0
        ? "profit"
        : changePercent < 0
          ? "loss"
          : "breakeven"
  };
});

// Return the portfolio price analysis
return [
  {
    json: {
      selected_trade_date: input.selected_trade_date,
      total_symbols: results.length,
      matched_symbols: results.filter(item => item.close !== null).length,
      results
    }
  }
];

const input = $input.first().json;

const CONFIG = {
  MIN_CHANGE_PERCENT: 2,
  MIN_SELLABLE_QUANTITY: 0,
  PRICE_ROUNDING: "ROUND",
  SELL_RATIO: 1,
  INCLUDE_ZERO_PRICE: false,
};

function roundPrice(price) {
  switch (CONFIG.PRICE_ROUNDING) {
    case "FLOOR":
      return Math.floor(price);
    case "CEIL":
      return Math.ceil(price);
    case "ROUND":
    default:
      return Math.round(price);
  }
}

const orders = (input.results || [])
  .filter(stock =>
    stock.changePercent !== null &&
    Number(stock.changePercent) >= CONFIG.MIN_CHANGE_PERCENT &&
    Number(stock.sellableQuantity) > CONFIG.MIN_SELLABLE_QUANTITY
  )
  .map(stock => {
    const quantity = Math.floor(
      Number(stock.sellableQuantity) * CONFIG.SELL_RATIO
    );

    const price = Number(stock.close).toFixed(0);

    return {
      symbol: stock.symbol,
      quantity,
      price: String(price)
    };
  })
  .filter(order =>
    order.quantity > 0 &&
    (CONFIG.INCLUDE_ZERO_PRICE || Number(order.price) > 0)
  );

return [
  {
    json: {
      orders,
      selected_trade_date: input.selected_trade_date
    }
  }
];

// Retrieve data from the previous node
const inputData = $input.first().json;

// Extract the result array containing stock details
const results = inputData.result || [];

// Transform each stock entry into the required order payload structure
const orders = results
    .map(item => {
        return {
            symbol: item.symbol,
            quantity: Math.round(item.suggested_shares),
            price: String(Number((item.pivot_s1_plus_1).toFixed(1)*1000))
        };
    })
    .filter(order => order.quantity !== 0);

// Return the formatted output payload containing the orders array
return [{
    json: {
        body: {
          access_token: inputData.accessToken,
          orders: orders,
          selected_trade_date: inputData.result[0].calculated_for_date
        }
    }
}];
